def valid(batch):
    return all(r["amount"] >= 0 for r in batch)
tests = []
def find_bad(batch):
    tests.append([r["id"] for r in batch])
    if len(batch) == 1:
        return batch[0]["id"]
    mid = len(batch) // 2
    left, right = batch[:mid], batch[mid:]
    if not valid(left):
        return find_bad(left)
    return find_bad(right)
